import { Effect, Layer, ServiceMap } from "effect"

export interface Shipment {
  readonly id: string
  readonly recipient: string
  readonly postalCode: string
}

export class LabelSettings extends ServiceMap.Service<LabelSettings, {
  readonly prefix: string
  readonly warehouse: string
}>()("fulfillment/LabelSettings") {}

export class LabelStore extends ServiceMap.Service<LabelStore, {
  readonly write: (key: string, contents: string) => Effect.Effect<void>
}>()("fulfillment/LabelStore") {}

export class ShippingLabels extends ServiceMap.Service<ShippingLabels, {
  readonly publish: (shipment: Shipment) => Effect.Effect<string>
}>()("fulfillment/ShippingLabels") {}

export const ShippingLabelsLive = Layer.effect(
  ShippingLabels,
  Effect.gen(function*() {
    const store = yield* LabelStore
    const settings = yield* LabelSettings

    const keyFor = (shipment: Shipment): string =>
      `${settings.prefix}/${shipment.id}.json`

    const serialize = (shipment: Shipment): string =>
      JSON.stringify({
        shipmentId: shipment.id,
        recipient: shipment.recipient,
        postalCode: shipment.postalCode,
        warehouse: settings.warehouse
      })

    const publish = (shipment: Shipment) =>
      Effect.gen(function*() {
        const key = keyFor(shipment)
        yield* store.write(key, serialize(shipment))
        return key
      })

    return { publish }
  })
)
